<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeKeyVO;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurposeKeyOptions;

final class ConsentPurposeKeyVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = ConsentPurposeKeyOptions::MARKETING;
        $ref = ConsentPurposeKeyVO::from($value);
        $this->assertEquals(ConsentPurposeKeyOptions::MARKETING, $ref->value());
        $other = ConsentPurposeKeyVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = ConsentPurposeKeyVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = ConsentPurposeKeyVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(ConsentPurposeKeyVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = ConsentPurposeKeyVO::from(ConsentPurposeKeyOptions::MARKETING);
        $same = ConsentPurposeKeyVO::from(ConsentPurposeKeyOptions::MARKETING);
        $other = ConsentPurposeKeyVO::from(ConsentPurposeKeyOptions::ANALYTICS);
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
}
